function stripHtml(value) {
  return String(value || '')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&#39;/gi, "'")
    .replace(/&quot;/gi, '"')
    .replace(/\s+/g, ' ')
    .trim();
}

function fieldTextFromHtml(value) {
  return String(value || '')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<br\s*\/?\s*>/gi, '\n')
    .replace(/<\/(?:p|div|tr|li|h[1-6])\s*>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&#39;/gi, "'")
    .replace(/&quot;/gi, '"')
    .replace(/\r/g, '')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function extractLatestAuthoredText(htmlValue, fallbackValue) {
  const html = String(htmlValue || '');
  const htmlMarkers = [
    /<div[^>]+id=["']divRplyFwdMsg["'][^>]*>/i,
    /<div[^>]+class=["'][^"']*gmail_quote[^"']*["'][^>]*>/i,
    /<blockquote[^>]*(?:type=["']cite["'])?[^>]*>/i,
    /<!--\s*Original Message\s*-->/i,
  ];
  let htmlCut = html.length;
  for (const marker of htmlMarkers) {
    const match = marker.exec(html);
    if (match && match.index < htmlCut) htmlCut = match.index;
  }
  const text = fieldTextFromHtml(html ? html.slice(0, htmlCut) : fallbackValue || '');
  const lines = text.split('\n');
  const textMarkers = [
    /^\s*-{2,}\s*(?:ursprüngliche nachricht|original message)\s*-{2,}\s*$/i,
    /^\s*(?:von|from)\s*:\s*.+$/i,
    /^\s*(?:gesendet|sent)\s*:\s*.+$/i,
    /^\s*am\s+.+\s+schrieb\s+.+:\s*$/i,
    /^\s*on\s+.+\s+wrote\s*:\s*$/i,
  ];
  const markerIndex = lines.findIndex((line) => textMarkers.some((marker) => marker.test(line)));
  return lines.slice(0, markerIndex >= 0 ? markerIndex : lines.length).join('\n').trim().slice(0, 12000);
}

function chooseCurrentMessage(messages, normalized) {
  const rows = Array.isArray(messages) ? messages : [];
  const exactId = rows.find((message) => String(message.id || '') === String(normalized.messageId || ''));
  if (exactId) return exactId;
  const exactInternetId = rows.find((message) => String(message.internetMessageId || '').toLowerCase() === String(normalized.internetMessageId || '').toLowerCase());
  if (exactInternetId) return exactInternetId;
