function extractText(value) {
  if (!value || typeof value !== 'object') return String(value || '');
  if (typeof value.text === 'string') return value.text;
  if (typeof value.response === 'string') return value.response;
  if (typeof value.mergedResponse === 'string') return value.mergedResponse;
  if (Array.isArray(value.content)) return value.content.map((part) => part?.text || '').join('\n');
  if (Array.isArray(value.output)) return value.output.flatMap((item) => item?.content || []).map((part) => part?.text || '').join('\n');
  return '';
}

function escapeHtml(value) {
  return String(value || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

const meta = $('Apply Approved Style Profile').first().json;
const rawText = extractText($input.first().json).trim();
const validationReasons = [];
let parsed;
try {
  parsed = JSON.parse(rawText.replace(/^\x60{3}(?:json)?\s*/i, '').replace(/\s*\x60{3}$/, ''));
} catch (error) {
  validationReasons.push('invalid_json');
  parsed = {};
}

const requiredOutputKeys = ['category', 'confidence', 'language', 'risk_level', 'needs_human_approval', 'greeting', 'paragraphs', 'closing', 'facts_used', 'blocked_reasons', 'missing_information'];
const parsedKeys = parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? Object.keys(parsed).sort() : [];
if (JSON.stringify(parsedKeys) !== JSON.stringify([...requiredOutputKeys].sort())) validationReasons.push('invalid_output_schema');

const categories = new Set(['shipping', 'returns', 'invoice', 'product', 'complaint', 'general']);
const riskLevels = new Set(['low', 'medium', 'high']);
const category = categories.has(parsed.category) ? parsed.category : 'general';
const confidence = Number.isFinite(Number(parsed.confidence)) ? Math.max(0, Math.min(1, Number(parsed.confidence))) : 0;
const riskLevel = riskLevels.has(parsed.risk_level) ? parsed.risk_level : meta.deterministicRiskLevel;
const expectedLanguage = meta.expectedLanguage === 'en' ? 'en' : 'de';
const replyLengthClass = ['ack_only', 'simple', 'complex'].includes(meta.replyLengthClass) ? meta.replyLengthClass : 'simple';
const replyLengthLimits = meta.replyLengthLimits && typeof meta.replyLengthLimits === 'object'
  ? meta.replyLengthLimits
  : { max_paragraphs: 3, max_characters: 1400 };
let greeting = String(parsed.greeting || '').trim();
let paragraphs = Array.isArray(parsed.paragraphs) ? parsed.paragraphs.map((p) => String(p || '').trim()).filter(Boolean) : [];
let closing = String(parsed.closing || '').trim();
const factsUsed = Array.isArray(parsed.facts_used) ? parsed.facts_used : [];
const allowedFactIds = new Set(Array.isArray(meta.allowedCustomerFactIds) ? meta.allowedCustomerFactIds : []);
const factUseIds = factsUsed.map((entry) => String(entry?.fact_id || '').trim()).filter(Boolean);
const factsUsedValid = factsUsed.length <= 20 && factsUsed.every((entry) =>
  entry && typeof entry === 'object' && !Array.isArray(entry)
  && Object.keys(entry).length === 1
  && typeof entry.fact_id === 'string'
  && allowedFactIds.has(entry.fact_id)
);

if (parsed.needs_human_approval !== true) validationReasons.push('approval_flag_missing');
if (!categories.has(parsed.category)) validationReasons.push('invalid_category');
if (!riskLevels.has(parsed.risk_level)) validationReasons.push('invalid_risk');
if (!['de', 'en'].includes(parsed.language) || parsed.language !== expectedLanguage) validationReasons.push('invalid_language');
if (!Array.isArray(parsed.blocked_reasons) || parsed.blocked_reasons.some((value) => typeof value !== 'string')) validationReasons.push('invalid_blocked_reasons');
if (!Array.isArray(parsed.missing_information) || parsed.missing_information.some((value) => typeof value !== 'string')) validationReasons.push('invalid_missing_information');
if (!factsUsedValid) validationReasons.push('invalid_fact_references');
if (!greeting || greeting.length > 180) validationReasons.push('invalid_greeting');
if (
  paragraphs.length < 1
  || paragraphs.length > Number(replyLengthLimits.max_paragraphs || 3)
  || paragraphs.some((p) => p.length > 900)
  || paragraphs.join(' ').length > Number(replyLengthLimits.max_characters || 1400)
) validationReasons.push('invalid_paragraphs');
if (expectedLanguage === 'de' && !['Viele Grüße', 'Beste Grüße'].includes(closing)) validationReasons.push('invalid_closing');
if (expectedLanguage === 'en' && closing !== 'Best regards') validationReasons.push('invalid_closing');

const draftPlain = [greeting, ...paragraphs, closing].join('\n');
if (/<[^>]+>|\x60{3}|\[[^\]]+\]\([^\)]+\)/.test(draftPlain)) validationReasons.push('markup_detected');
try { if (/\p{Extended_Pictographic}/u.test(draftPlain)) validationReasons.push('emoji_detected'); } catch (error) {}
if (/liebe grüße|lg\b|herzliche grüße/i.test(draftPlain)) validationReasons.push('forbidden_closing');
